fn row(o:&Op)->Row{[o.kind as u64,o.q_control2.0,o.q_control1.0,o.q_target.0,o.c_target.0,o.c_condition.0,o.r_target.0]}
fn op(r:&Row)->Op{let mut o=Op::empty();o.kind=match r[0]{6=>K::X,8=>K::CX,9=>K::CZ,10=>K::Swap,12=>K::Hmr,13=>K::CCX,15=>K::PushCondition,16=>K::PopCondition,_=>panic!("retained product unsupported IR kind")};o.q_control2=QubitId(r[1]);o.q_control1=QubitId(r[2]);o.q_target=QubitId(r[3]);o.c_target.0=r[4];o.c_condition.0=r[5];o.r_target.0=r[6];o}
pub(super) fn run(ops:Vec<Op>)->Vec<Op>{
 assert_eq!(ops.len(),11631083,"retained product input count");let mut h=Sha3_256::new();for o in &ops{h.update((o.kind as u32).to_le_bytes());h.update([0u8;4]);for v in row(o).iter().skip(1){h.update(v.to_le_bytes());}}
 assert_eq!(format!("{:x}",h.finalize()),"ef26d666aa1356cdb61d990733fa58b7d651a23616f727cd1463b2d21286aadd","retained product input hash");
 let mut out=Vec::with_capacity(ops.len()+256);let mut next=0usize;
 for (i,o) in ops.into_iter().enumerate(){if next<ACTIONS.len()&&i as u64==ACTIONS[next].0{let a=&ACTIONS[next];assert_eq!(row(&o),a.1,"retained product event");let rs=a.2;for r in rs{if *r==a.1{out.push(o);}else{out.push(op(r));}}next+=1;}else{out.push(o);}}
 assert_eq!(next,ACTIONS.len(),"retained product activation");out
}
